// bind converts one of your checks into the form the runner uses, tying
// it to this run's sample inputs — which is what lets a check you wrote
// see the same values, and the same overrides, as the generated ones.
func (c LifecycleCheck) bind(
	fx LifecycleFixture,
) (suite.Check[Lifecycle], error) {
	out := suite.Check[Lifecycle]{
		Claim: c.Claim, Class: c.Class, Needs: c.Needs,
	}
	if out.Class == "" {
		out.Class = suite.ClassHandWritten
	}

	var err error

	// bodies counts what this row set and the runtime refuses any answer
	// but one; fields is the listing that refusal offers, which has to
	// name what THIS interface can set; scoped says the body it set is
	// one that reads the row's Method. A contributing tier's dispatch
	// lands below and may move all three.
	bodies, fields, scoped := 0, "Run, RunWith", false
	if c.Run != nil {
		scoped = true
		bodies++
		if out.ID, err = suite.RowID("Run", c.Method, c.Name, lifecycleMethods); err != nil {
			return out, err
		}
		run := c.Run
		out.Run = func(tb testing.TB, s Lifecycle) {
			run(tb, s, fx)
		}
	}
	if c.RunWith != nil {
		bodies++
		out.ID = suite.HandRowID(c.Name)
		rw := c.RunWith
		out.RunWith = func(tb testing.TB, sub LifecycleSubject) {
			rw(tb, sub, fx)
		}
	}
	fields += ", Prop"
	if c.Prop != nil {
		scoped = true
		bodies++
		if out.ID, err = suite.RowID("Prop", c.Method, c.Name, lifecycleMethods); err != nil {
			return out, err
		}
		fn := c.Prop
		out.RunWith = func(tb testing.TB, sub suite.Subject[Lifecycle]) {
			model.Check(tb, func(rt *PropT) {
				fn(rt, sub.New(tb), fx)
			})
		}
	}
	if err := suite.OneBody(c.Name, bodies, fields); err != nil {
		return out, err
	}
	if c.Method != "" && !scoped {
		return out, fmt.Errorf(
			"check %q sets Method, but its body fixes its own scope; drop Method", c.Name)
	}
	if out.Falsifiable, err = suite.Falsify(c.Name, c.ProvenBy != nil, c.Argued); err != nil {
		return out, err
	}
	return out, nil
}

// RunLifecycle runs every check — the generated ones and any you
// wrote — against every implementation you pass it.
//
// Each argument describes one thing to do, in any order: an
// implementation to test, a table of your own checks, sample inputs to
// use, or checks to leave out.
//
//	RunLifecycle(t,
//		LifecycleHarness[*InMemory]{Name: "in-memory", New: NewInMemory},
//		LifecycleSuite.Without(LifecycleSuite.Checks.Close.Smoke()),
//	)
//
// Pass two implementations to compare them against each other, and mark
// the one you trust as the Oracle. Every check runs as its own subtest
// named after the implementation and the check, so `go test -run` can
// select one.
//
// A check that needs something your implementation has not supplied
// fails rather than skipping, and says which field to fill in. That is
// deliberate: a skipped check is how a claim goes unchecked while the
// run stays green.
func RunLifecycle(
	t *testing.T, opts ...LifecycleRunOpt,
) {
	t.Helper()
	var rc lifecycleRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := lifecycleNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	// Checked here, after reading every argument and before running
	// anything: a misconfigured run reports all of its problems at once
	// rather than one per attempt.
	rc.Fail(t, "RunLifecycle")
	suite.Run(t,
		lifecycleSuite().With(rc.Extra...).Without(rc.Drops...),
		rc.Subjects...)
}

